package org.openenglish.reader;
import android.app.*;import android.content.*;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.speech.tts.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.text.SimpleDateFormat;
/** Native bilingual reading with installed offline English TTS. */
public final class ReadingActivity extends Activity {
 private static final int INK=0xff193b36,GREEN=0xff177c6d,MUTED=0xff71827c,BG=0xfff5f8f4;
 private SharedPreferences prefs;private JSONObject progress;private JSONArray stories;private LinearLayout body;private TextView timer,voiceStatus;private ReadingAudio sound;private StudioStore store;private boolean voiceReady,foreground,translation=true,continuous,reviewMode;private int selected=-1,paragraph,utterance;private float speed=.9f;private String activeWord="";private boolean answer;private long lastTick,lastSaved;private Runnable speechWatchdog;
  private final Handler ui=new Handler(Looper.getMainLooper());
 private String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
 private void save(){prefs.edit().putString("reading_state",progress.toString()).apply();}
 private void accrue(){try{long now=SystemClock.elapsedRealtime();ReadingProgress.rollDay(progress,today());if(foreground&&(selected>=0||reviewMode)&&lastTick>0){long seconds=Math.min(5,Math.max(0,(now-lastTick)/1000));if(seconds>0){progress.put("seconds",Math.min(86400,progress.getLong("seconds")+seconds));lastTick+=seconds*1000;}}else lastTick=now;}catch(Exception e){toast("阅读计时暂不可用");}}
 private final Runnable tick=new Runnable(){public void run(){if(!foreground)return;accrue();updateTimer();if(SystemClock.elapsedRealtime()-lastSaved>=15000){save();lastSaved=SystemClock.elapsedRealtime();}ui.postDelayed(this,1000);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("studio",0);store=new StudioStore(this);try{String raw=prefs.getString("reading_state","");if(raw.isEmpty())progress=ReadingProgress.fresh();else{ReadingProgress.validate(raw);progress=new JSONObject(raw);}stories=new JSONObject(AiClient.read(getAssets().open("reading.json"),200000)).getJSONArray("stories");ReadingProgress.rollDay(progress,today());}catch(Exception e){new AlertDialog.Builder(this).setMessage("阅读数据未能读取，请保留数据并重新打开。").setPositiveButton("返回",(d,n)->finish()).setCancelable(false).show();return;}
  getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);setVolumeControlStream(android.media.AudioManager.STREAM_MUSIC);if(state!=null){selected=state.getInt("selected",-1);paragraph=state.getInt("paragraph",0);translation=state.getBoolean("translation",true);speed=state.getFloat("speed",.9f);reviewMode=state.getBoolean("review",false);}
  sound=new ReadingAudio(this,message->{if(voiceStatus!=null)voiceStatus.setText(message);});
  if(reviewMode)showReview();else if(selected>=0&&selected<stories.length())showStory(true);else showShelf();
 }
 private JSONObject story(){return selected>=0&&selected<stories.length()?stories.optJSONObject(selected):null;}
 private int dp(int n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
 private GradientDrawable bg(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(18));return d;}
 private TextView text(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setLineSpacing(dp(5),1.1f);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
 private void add(LinearLayout l,View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(12);l.addView(v,p);}
 private TextView button(String s,Runnable action){TextView v=text(s,16,GREEN,true);v.setGravity(Gravity.CENTER);v.setPadding(dp(14),dp(14),dp(14),dp(14));v.setMinHeight(dp(48));v.setBackground(bg(0xffe2eee7));v.setOnClickListener(w->action.run());return v;}
 private LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(18),dp(16),dp(18),dp(20));l.setBackground(bg(0xffffffff));add(body,l);return l;}
 private void shell(String title){accrue();LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);setContentView(root);root.addView(button("‹  "+title,()->{if(selected>=0||reviewMode)showShelf();else finish();}));ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(20),dp(10),dp(20),dp(28));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));timer=text("",13,MUTED,false);add(body,timer);updateTimer();voiceStatus=text("",12,MUTED,false);add(body,voiceStatus);updateVoice();lastTick=SystemClock.elapsedRealtime();}
 private void updateTimer(){if(timer!=null&&progress!=null)timer.setText("今日阅读 / 复习 "+progress.optLong("seconds")/60+" 分 "+progress.optLong("seconds")%60+" 秒  /  10 分钟");}
 private void updateVoice(){if(voiceStatus!=null)voiceStatus.setText("本地合成听读 · "+speed+" 倍速");}
 private void stopVoice(){continuous=false;utterance++;if(sound!=null)sound.stop();}
 private void speak(String s,boolean all){stopVoice();continuous=all;final int token=utterance;if(!foreground)return;sound.play(s,speed,()->{if(!foreground||!continuous||token!=utterance)return;JSONObject book=story();if(book==null)return;if(paragraph+1<book.optJSONArray("paragraphs").length()){paragraph++;showStory(false);speak(book.optJSONArray("paragraphs").optJSONObject(paragraph).optString("en"),true);}else{continuous=false;toast("本篇听读完成");}});}
 private void showShelf(){accrue();stopVoice();selected=-1;reviewMode=false;shell("双语阅读");LinearLayout c=card();int done=progress.optInt("completed"),step=Math.min(17,done);JSONObject next=stories.optJSONObject(step);String phase="读听 · 复习 · 说一说";add(c,text("每天读 10 分钟",26,INK,true));add(c,text("18 次学习路线 · 已完成 "+done+" / 18\n"+(done>=18?"路线完成，可继续自由阅读":"第 "+(step+1)+" 次 · "+phase+"\n"+next.optString("title")),15,MUTED,false));add(c,button("开始今日学习",()->{open(step);}));add(c,button("完成今日 10 分钟",()->{try{accrue();if(ReadingProgress.finish(progress,today())){save();showShelf();toast("今天已完成，明天继续");}else toast(progress.optLong("seconds")<600?"还差 "+(600-progress.optLong("seconds"))+" 秒阅读或复习时间":"今日已记录，或路线已完成");}catch(Exception e){toast("进度保存失败");}}));add(body,button("词汇卡片 · "+progress.optJSONObject("cards").length()+" 个收藏",this::showReview));add(body,button("视频与字幕学习",()->{startActivity(new Intent(this,StudioActivity.class).putExtra("open_material_library",true));finish();}));add(body,text("原创双语短篇 · A2—B1",21,INK,true));for(int i=0;i<stories.length();i++){final int index=i;JSONObject s=stories.optJSONObject(i);LinearLayout book=card();add(book,text(s.optString("title"),21,INK,true));add(book,text(s.optString("zhTitle")+" · "+s.optString("level")+" · 3 段",14,MUTED,false));add(book,button("继续阅读",()->open(index)));}add(body,text("18 篇原创短篇、90 张配套词卡。听读为本地合成语音。影视练习可回到首页材料库，导入自己的视频与字幕。",13,MUTED,false));}
 private void open(int index){accrue();selected=index;reviewMode=false;paragraph=progress.optJSONObject("positions").optInt(story().optString("id"),0);showStory(true);}
 private void showStory(boolean stop){if(stop)stopVoice();JSONObject s=story();if(s==null){showShelf();return;}reviewMode=false;JSONArray paragraphs=s.optJSONArray("paragraphs");paragraph=Math.max(0,Math.min(paragraphs.length()-1,paragraph));try{progress.getJSONObject("positions").put(s.getString("id"),paragraph);save();}catch(Exception e){toast("位置未能保存");}shell(s.optString("zhTitle"));add(body,text(s.optString("title"),27,INK,true));add(body,text(s.optString("level")+" · 第 "+(paragraph+1)+" / "+paragraphs.length()+" 段",13,MUTED,false));JSONObject p=paragraphs.optJSONObject(paragraph);LinearLayout c=card();TextView english=text(p.optString("en"),23,INK,false);clickWords(english,p.optString("en"));add(c,english);if(translation)add(c,text(p.optString("zh"),17,MUTED,false));add(body,button(translation?"隐藏中文 · 先读英文":"显示中文译文",()->{translation=!translation;showStory(true);}));add(body,button("▶ 听本段",()->speak(p.optString("en"),false)));add(body,button("▶ 从本段连续听读",()->speak(p.optString("en"),true)));add(body,button("停止听读",this::stopVoice));add(body,button("语速 "+speed+" · 点击切换",()->{speed=speed==.75f?.9f:speed==.9f?1f:.75f;showStory(true);}));if(paragraph>0)add(body,button("上一段",()->{paragraph--;showStory(true);}));if(paragraph+1<paragraphs.length())add(body,button("下一段",()->{paragraph++;showStory(true);}));else add(body,button("读完了 · 去复习词汇",this::showReview));add(body,button("说一说 · 用自己的话",()->new AlertDialog.Builder(this).setTitle("用英文试一试").setMessage(s.optString("prompt")+"\n\n"+s.optString("prompt_zh")).setPositiveButton("打开自由对话",(d,n)->startActivity(new Intent(this,StudioActivity.class).putExtra("free_tutor",true))).setNegativeButton("自己练习",null).show()));add(body,text("点击词汇，查看释义与收藏",18,INK,true));JSONArray words=s.optJSONArray("words");for(int i=0;i<words.length();i++){JSONObject w=words.optJSONObject(i);add(body,button(w.optString("en"),()->word(w)));}}

 private void clickWords(TextView v,String raw){android.text.SpannableString s=new android.text.SpannableString(raw);java.util.regex.Matcher match=java.util.regex.Pattern.compile("[A-Za-z]+(?:'[A-Za-z]+)?").matcher(raw);while(match.find()){final String word=match.group();s.setSpan(new android.text.style.ClickableSpan(){public void onClick(View view){lookup(word);}public void updateDrawState(android.text.TextPaint paint){paint.setColor(INK);paint.setUnderlineText(false);}},match.start(),match.end(),android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}v.setText(s);v.setMovementMethod(android.text.method.LinkMovementMethod.getInstance());}
 private void lookup(String query){final int token=utterance;new Thread(()->{JSONObject entry=null;try{entry=OfflineDictionary.lookup(getApplicationContext(),query);}catch(Exception ignored){}final JSONObject found=entry;ui.post(()->{if(isDestroyed()||!foreground||token!=utterance)return;if(found==null){toast("离线词典暂未收录这个词");return;}try{word(new JSONObject().put("en",found.optString("word",query)).put("zh",found.optString("translation").replace("\\n","\n")));}catch(Exception ignored){toast("释义暂未能读取");}});},"reading-dictionary").start();}
 private void word(JSONObject w){String en=w.optString("en");new AlertDialog.Builder(this).setTitle(en).setMessage(w.optString("zh")).setNeutralButton("听发音",(d,n)->speak(en,false)).setNegativeButton("返回",null).setPositiveButton("收藏词卡",(d,n)->{try{JSONObject cards=progress.getJSONObject("cards");if(!cards.has(en)&&cards.length()>=500){toast("词卡已达到 500 个，请先整理收藏");return;}String meaning=w.getString("zh");if(!cards.has(en))cards.put(en,new JSONObject().put("zh",meaning.length()>120?meaning.substring(0,120):meaning).put("due",0).put("interval",0).put("reviews",0));store.add("word",en,w.getString("zh"));save();toast("已收藏到词汇卡片与原有词库");}catch(Exception e){toast("收藏未能保存");}}).show();}
 private void showReview(){accrue();stopVoice();selected=-1;reviewMode=true;answer=false;activeWord="";shell("词汇卡片");JSONObject cards=progress.optJSONObject("cards");List<String> due=new ArrayList<>();Iterator<String> it=cards.keys();long now=System.currentTimeMillis();while(it.hasNext()){String k=it.next();if(cards.optJSONObject(k).optLong("due")<=now)due.add(k);}Collections.sort(due,(a,b)->Long.compare(cards.optJSONObject(a).optLong("due"),cards.optJSONObject(b).optLong("due")));add(body,text("收藏 "+cards.length()+" 个 · 到期 "+due.size()+" 个",16,MUTED,false));if(due.isEmpty())add(body,text(cards.length()==0?"先读一篇故事，点击配套词汇收藏。":"到期词卡已复习完，明天再来。",18,INK,false));else{activeWord=due.get(0);LinearLayout c=card();add(c,text(activeWord,30,INK,true));add(c,button("听发音",()->speak(activeWord,false)));TextView meaning=text("先回想中文含义",18,MUTED,false);add(c,meaning);add(c,button("翻面 · 查看释义",()->{answer=true;meaning.setText(cards.optJSONObject(activeWord).optString("zh"));}));add(c,button("还没记住 · 10 分钟后复习",()->rate(false)));add(c,button("记住了 · 延后复习",()->rate(true)));}List<String> all=new ArrayList<>();it=cards.keys();while(it.hasNext())all.add(it.next());Collections.sort(all);for(String k:all){LinearLayout c=card();add(c,text(k+" · "+cards.optJSONObject(k).optString("zh"),17,INK,false));add(c,button("听发音",()->speak(k,false)));add(c,button("移除收藏",()->new AlertDialog.Builder(this).setMessage("移除 "+k+" 的词卡？").setNegativeButton("保留",null).setPositiveButton("移除",(d,n)->{cards.remove(k);save();showReview();}).show()));}}
 private void rate(boolean known){if(!answer){toast("先回想，再翻面查看释义");return;}try{JSONObject cards=progress.getJSONObject("cards");cards.put(activeWord,ReadingProgress.review(cards.getJSONObject(activeWord),known,System.currentTimeMillis()));save();showReview();}catch(Exception e){toast("复习记录未能保存");}}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 @Override protected void onResume(){super.onResume();foreground=true;lastTick=SystemClock.elapsedRealtime();if(progress!=null)ui.post(tick);}
 @Override protected void onPause(){if(progress!=null)accrue();foreground=false;stopVoice();ui.removeCallbacks(tick);if(progress!=null)save();super.onPause();}
 @Override protected void onSaveInstanceState(Bundle s){super.onSaveInstanceState(s);s.putInt("selected",selected);s.putInt("paragraph",paragraph);s.putBoolean("translation",translation);s.putFloat("speed",speed);s.putBoolean("review",reviewMode);}
 @Override public void onBackPressed(){if(selected>=0||reviewMode)showShelf();else super.onBackPressed();}
 @Override protected void onDestroy(){ui.removeCallbacksAndMessages(null);if(sound!=null)sound.close();if(store!=null)store.close();super.onDestroy();}
}
